CREATE TABLE public.biz_demo_sets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id),payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),revision int NOT NULL DEFAULT 0,UNIQUE(owner_id));
GRANT SELECT ON public.biz_demo_sets TO authenticated;GRANT ALL ON public.biz_demo_sets TO service_role;
ALTER TABLE public.biz_demo_sets ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.biz_demo_can() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND status='Đang hoạt động') AND (public.is_super_admin(auth.uid()) OR private.sig_can(auth.uid(),'biz.demo_manage'))$$;
CREATE POLICY biz_demo_read ON public.biz_demo_sets FOR SELECT TO authenticated USING(owner_id=auth.uid() AND public.biz_demo_can());
CREATE FUNCTION public.biz_demo_build() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE roster_ jsonb;facts_ jsonb:='[]';docs_ jsonb:='[]';person record;k record;m int;i int:=0;annual_ numeric;target_ numeric;actual_ numeric;weight_ int[]:=ARRAY[7,6,8,7,8,9,8,9,10,9,9,10];running_ numeric;status_ text;first_ timestamptz;deadline_ timestamptz;workflow_ jsonb;id_ text;goal_ jsonb:='[]';months_ jsonb;BEGIN
IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin khởi tạo DEMO.';END IF;
SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',q.user_id,'employee_name',q.full_name,'department_id',q.department_id,'department_name',q.name,'system_id',q.system_id,'team_id',q.team_id)),'[]') INTO roster_ FROM (SELECT DISTINCT ON(m.user_id) m.user_id,p.full_name,d.id department_id,d.name,d.system_id,(SELECT tm.team_id FROM public.biz_team_members tm WHERE tm.user_id=m.user_id AND tm.ended_at IS NULL LIMIT 1) team_id FROM public.biz_department_members m JOIN public.profiles p ON p.id=m.user_id JOIN public.biz_departments d ON d.id=m.department_id JOIN public.biz_systems s ON s.id=d.system_id WHERE m.ended_at IS NULL AND p.status='Đang hoạt động' AND d.active AND s.active AND NOT public.is_super_admin(p.id) AND s.name NOT ILIKE '%Bán Lẻ%' AND s.name NOT ILIKE '%Showroom%' ORDER BY m.user_id,m.started_at DESC) q;
FOR person IN SELECT * FROM jsonb_to_recordset(roster_) r(user_id uuid,employee_name text,department_id uuid,department_name text,system_id uuid,team_id uuid) LOOP
 i:=i+1;SELECT to_jsonb(w) INTO workflow_ FROM public.biz_approval_workflows w WHERE w.active AND w.system_id=person.system_id AND (w.department_id IS NULL OR w.department_id=person.department_id) AND w.kind='goal_year' AND w.effective_from<=now() ORDER BY (w.department_id IS NOT NULL) DESC,w.effective_from DESC LIMIT 1;
 FOR k IN SELECT * FROM public.biz_kr_metrics WHERE department_id=person.department_id AND active LOOP
 annual_:=CASE WHEN k.value_kind='money' THEN (1500000000+i*350000000) WHEN k.name ILIKE '%đại lý%' THEN 12+i*3 ELSE 50+i*15 END;running_:=0;months_:='[]';
 FOR m IN 1..12 LOOP target_:=CASE WHEN m=12 THEN annual_-running_ ELSE floor(annual_*weight_[m]/100) END;running_:=running_+target_;months_:=months_||to_jsonb(target_::text);
 actual_:=CASE WHEN m>=10 OR (m=8 AND i%3=0) THEN NULL ELSE round(target_*(CASE i%5 WHEN 0 THEN 1.25 WHEN 1 THEN 1 WHEN 2 THEN 0.95 WHEN 3 THEN 0.65 ELSE 0.45 END)*(CASE m%3 WHEN 0 THEN 1.1 WHEN 1 THEN 0.9 ELSE 1 END)) END;
 facts_:=facts_||jsonb_build_array(jsonb_build_object('user_id',person.user_id,'employee_name',person.employee_name,'department_id',person.department_id,'department_name',person.department_name,'system_id',person.system_id,'team_id',person.team_id,'month',m,'baseline_id','demo-goal-'||person.user_id,'target_version_id','demo-goal-'||person.user_id,'metric_id',k.id,'definition',jsonb_build_object('name',k.name,'unit',k.unit,'aggregation',k.aggregation,'direction',k.direction,'value_kind',k.value_kind),'target',target_::text,'actual',actual_::text,'official',m<=7,'year',2026));END LOOP;
 goal_:=goal_||jsonb_build_array(jsonb_build_object('id','demo-goal-'||person.user_id||'-'||k.id,'user_id',person.user_id,'employee_name',person.employee_name,'department_id',person.department_id,'system_id',person.system_id,'team_id',person.team_id,'year',2026,'metric_id',k.id,'definition',jsonb_build_object('name',k.name,'unit',k.unit,'aggregation',k.aggregation,'direction',k.direction,'value_kind',k.value_kind),'annual',annual_::text,'months',months_,'status',CASE i%4 WHEN 0 THEN 'draft' WHEN 1 THEN 'approved' WHEN 2 THEN 'pending' ELSE 'changes' END,'workflow',workflow_));END LOOP;
 FOR m IN 1..12 LOOP
 deadline_:=make_timestamptz(2026,m,5,17,0,0,'Asia/Ho_Chi_Minh');first_:=CASE WHEN (m+i)%6 IN (2,3) THEN NULL WHEN (m+i)%6=1 THEN deadline_+interval '1 day' ELSE deadline_-interval '1 day' END;
 docs_:=docs_||jsonb_build_array(jsonb_build_object('id','demo-plan-'||person.user_id||'-'||m,'kind','plan','period_kind','month','period',m,'year',2026,'user_id',person.user_id,'employee_name',person.employee_name,'department_id',person.department_id,'department_name',person.department_name,'system_id',person.system_id,'team_id',person.team_id,'deadline',deadline_,'first_submitted_at',first_,'resubmitted_at',CASE WHEN (m+i)%6=5 THEN deadline_+interval '2 days' END,'time_status',CASE WHEN first_ IS NOT NULL AND first_<=deadline_ THEN 'ontime' WHEN first_ IS NOT NULL THEN 'late' WHEN deadline_<now() THEN 'overdue' ELSE 'upcoming' END,'approval_status',CASE WHEN first_ IS NULL THEN 'draft' WHEN (m+i)%6=4 THEN 'changes' WHEN (m+i)%6=5 THEN 'resubmitted' ELSE 'submitted' END,'official',false,'sample_content','DỮ LIỆU DEMO — kế hoạch mô phỏng: phát triển khách hàng, chăm sóc cơ hội và rà soát mục tiêu tháng.','events',jsonb_build_array(jsonb_build_object('label','Khởi tạo giả lập','at',deadline_-interval '7 days','simulated',true))));
 status_:=CASE WHEN m>=10 OR (m=8 AND i%3=0) THEN 'draft' WHEN m<=7 THEN 'approved' WHEN i%2=0 THEN 'pending' ELSE 'changes' END;
 docs_:=docs_||jsonb_build_array(jsonb_build_object('id','demo-report-'||person.user_id||'-'||m,'kind','report','period_kind','month','period',m,'year',2026,'user_id',person.user_id,'employee_name',person.employee_name,'department_id',person.department_id,'department_name',person.department_name,'system_id',person.system_id,'team_id',person.team_id,'deadline',deadline_+interval '1 month','first_submitted_at',CASE WHEN status_='draft' THEN NULL ELSE deadline_+interval '25 days' END,'time_status',CASE WHEN status_='draft' THEN CASE WHEN deadline_+interval '1 month'<now() THEN 'overdue' ELSE 'upcoming' END ELSE 'ontime' END,'approval_status',status_,'official',status_='approved','sample_content','DỮ LIỆU DEMO — báo cáo mô phỏng, không phải kết quả kinh doanh hoặc tài liệu Google Docs thật.','workflow',workflow_,'current_step',0,'events',jsonb_build_array(jsonb_build_object('label','Khởi tạo giả lập','at',deadline_,'simulated',true))));END LOOP;
END LOOP;
RETURN jsonb_build_object('is_demo',true,'roster',roster_,'facts',facts_,'goals',goal_,'documents',docs_,'systems',(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') FROM public.biz_systems s),'departments',(SELECT coalesce(jsonb_agg(to_jsonb(d)),'[]') FROM public.biz_departments d),'teams',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM public.biz_teams t),'managers',(SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') FROM public.biz_management_assignments a),'appointments',(SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') FROM public.biz_appointments a),'created_at',now());END $$;
CREATE FUNCTION public.biz_demo_reset(_delete boolean DEFAULT false,_confirmed boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN
IF NOT public.biz_demo_can() OR NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin tạo/xóa DEMO.';END IF;IF NOT _confirmed THEN RAISE EXCEPTION 'Cần xác nhận thao tác DEMO.';END IF;
PERFORM pg_advisory_xact_lock(hashtext('biz_demo:'||auth.uid()));
IF _delete THEN DELETE FROM public.biz_demo_sets WHERE owner_id=auth.uid();ELSE INSERT INTO public.biz_demo_sets(owner_id,payload) VALUES(auth.uid(),public.biz_demo_build()) ON CONFLICT(owner_id) DO UPDATE SET payload=excluded.payload,revision=biz_demo_sets.revision+1,created_at=now();END IF;END $$;
CREATE FUNCTION public.biz_demo_read() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$BEGIN IF NOT public.biz_demo_can() THEN RAISE EXCEPTION 'Không có quyền DEMO.';END IF;RETURN (SELECT payload||jsonb_build_object('revision',revision,'server_now',now()) FROM public.biz_demo_sets WHERE owner_id=auth.uid());END $$;
CREATE FUNCTION public.biz_demo_dashboard(_filters jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$DECLARE p jsonb;f jsonb;r jsonb;o jsonb;lo int;hi int;m int;cum jsonb:='[]';q jsonb:='[]';sy jsonb:='[]';tm jsonb:='[]';cur int:=least(12,extract(month from now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::int);BEGIN
p:=public.biz_demo_read();IF p IS NULL THEN RETURN NULL;END IF;
lo:=CASE _filters->>'kind' WHEN 'month' THEN (_filters->>'period')::int WHEN 'quarter' THEN ((_filters->>'period')::int-1)*3+1 ELSE 1 END;hi:=CASE _filters->>'kind' WHEN 'month' THEN lo WHEN 'quarter' THEN lo+2 ELSE 12 END;
SELECT coalesce(jsonb_agg(x||jsonb_build_object('actual',CASE WHEN _filters->>'mode'='official' AND NOT (x->>'official')::boolean THEN NULL ELSE x->>'actual' END)),'[]') INTO f FROM jsonb_array_elements(p->'facts') x WHERE (_filters->>'department'='all' OR x->>'department_id'=_filters->>'department') AND (_filters->>'employee'='all' OR x->>'user_id'=_filters->>'employee') AND (coalesce(_filters->>'system','all')='all' OR x->>'system_id'=_filters->>'system') AND (coalesce(_filters->>'team','all')='all' OR x->>'team_id'=_filters->>'team') AND (x->>'year')::int=(_filters->>'year')::int;
SELECT coalesce(jsonb_agg(x),'[]') INTO r FROM jsonb_array_elements(p->'roster') x WHERE (_filters->>'department'='all' OR x->>'department_id'=_filters->>'department') AND (_filters->>'employee'='all' OR x->>'user_id'=_filters->>'employee') AND (coalesce(_filters->>'system','all')='all' OR x->>'system_id'=_filters->>'system') AND (coalesce(_filters->>'team','all')='all' OR x->>'team_id'=_filters->>'team');
SELECT coalesce(jsonb_agg(x),'[]') INTO o FROM jsonb_array_elements(p->'documents') x WHERE (x->>'year')::int=(_filters->>'year')::int AND (x->>'period')::int=CASE _filters->>'kind' WHEN 'month' THEN lo ELSE hi END AND EXISTS(SELECT 1 FROM jsonb_array_elements(r) z WHERE z->>'user_id'=x->>'user_id');
FOR m IN 1..12 LOOP cum:=cum||coalesce((SELECT jsonb_agg(x||jsonb_build_object('group_id',m::text,'group_name','Tháng '||m)) FROM jsonb_array_elements(public.biz_dashboard_aggregate(f,1,m)) x),'[]');END LOOP;
FOR m IN 1..4 LOOP q:=q||coalesce((SELECT jsonb_agg(x||jsonb_build_object('group_id',m::text,'group_name','Quý '||m)) FROM jsonb_array_elements(public.biz_dashboard_aggregate(f,(m-1)*3+1,m*3)) x),'[]');END LOOP;
RETURN jsonb_build_object('is_demo',true,'year',(_filters->>'year')::int,'period_kind',_filters->>'kind','period',(_filters->>'period')::int,'mode',_filters->>'mode','lo',lo,'hi',hi,'server_now',now(),'options_roster',p->'roster','roster',r,'facts',f,'obligations',o,'annual',public.biz_dashboard_aggregate(f,1,12),'current',public.biz_dashboard_aggregate(f,1,cur),'remaining','[]'::jsonb,'totals',public.biz_dashboard_aggregate(f,lo,hi),'months',public.biz_dashboard_aggregate(f,1,12,'month'),'quarters',q,'cumulative',cum,'departments',public.biz_dashboard_aggregate(f,lo,hi,'department'),'employees',public.biz_dashboard_aggregate(f,lo,hi,'employee'));END $$;
CREATE FUNCTION public.biz_demo_action(_id text,_action text,_data jsonb DEFAULT '{}') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE p jsonb;docs jsonb;row_ jsonb;idx int;steps_ int;BEGIN
IF NOT public.biz_demo_can() THEN RAISE EXCEPTION 'Không có quyền DEMO.';END IF;
SELECT payload INTO p FROM public.biz_demo_sets WHERE owner_id=auth.uid() FOR UPDATE;IF p IS NULL THEN RAISE EXCEPTION 'Chưa khởi tạo DEMO.';END IF;
SELECT x,ord::int-1 INTO row_,idx FROM jsonb_array_elements(p->'documents') WITH ORDINALITY e(x,ord) WHERE x->>'id'=_id;IF row_ IS NULL THEN RAISE EXCEPTION 'Không tìm thấy hồ sơ DEMO.';END IF;
IF _action NOT IN ('submit','revise','approve','return','override','actual') THEN RAISE EXCEPTION 'Thao tác DEMO không hợp lệ.';END IF;
IF row_->>'kind'='plan' AND _action IN ('approve','override') THEN RAISE EXCEPTION 'Kế hoạch không cần phê duyệt.';END IF;
IF _action='actual' THEN
IF _data->>'actual' IS NULL OR (_data->>'actual')::numeric<0 THEN RAISE EXCEPTION 'Thực tế phải không âm.';END IF;
SELECT jsonb_agg(CASE WHEN x->>'user_id'=row_->>'user_id' AND x->>'month'=row_->>'period' AND x->>'metric_id'=_data->>'metric_id' THEN x||jsonb_build_object('actual',_data->>'actual','official',false) ELSE x END) INTO docs FROM jsonb_array_elements(p->'facts') x;p:=jsonb_set(p,'{facts}',docs);
ELSE
IF _action IN ('revise','return','override') AND btrim(coalesce(_data->>'comment',''))='' THEN RAISE EXCEPTION 'Cần nội dung xử lý DEMO.';END IF;
IF _action IN ('approve','override') AND row_->>'workflow' IS NULL THEN RAISE EXCEPTION 'Chưa có quy trình thật để mô phỏng.';END IF;
steps_:=jsonb_array_length(coalesce(row_->'workflow'->'steps','[]'));IF _action='approve' AND coalesce((row_->>'current_step')::int,0)+1<steps_ THEN row_:=row_||jsonb_build_object('current_step',coalesce((row_->>'current_step')::int,0)+1);ELSE row_:=row_||jsonb_build_object('approval_status',CASE _action WHEN 'submit' THEN CASE WHEN row_->>'kind'='plan' THEN CASE WHEN row_->>'approval_status'='changes' THEN 'resubmitted' ELSE 'submitted' END ELSE 'pending' END WHEN 'approve' THEN 'approved' WHEN 'override' THEN 'approved' ELSE 'changes' END,'official',_action IN ('approve','override'));
IF _action IN ('approve','override') THEN SELECT jsonb_agg(CASE WHEN x->>'user_id'=row_->>'user_id' AND x->>'month'=row_->>'period' THEN x||jsonb_build_object('official',true) ELSE x END) INTO docs FROM jsonb_array_elements(p->'facts') x;p:=jsonb_set(p,'{facts}',docs);END IF;END IF;
IF _action='submit' THEN row_:=row_||jsonb_build_object('first_submitted_at',coalesce(row_->>'first_submitted_at',now()::text),'resubmitted_at',now(),'current_step',0);END IF;END IF;
row_:=row_||jsonb_build_object('events',coalesce(row_->'events','[]')||jsonb_build_array(jsonb_build_object('label',_action,'comment',_data->>'comment','at',now(),'simulated',true)));
p:=jsonb_set(p,ARRAY['documents',idx::text],row_);UPDATE public.biz_demo_sets SET payload=p,revision=revision+1 WHERE owner_id=auth.uid();END $$;
REVOKE ALL ON FUNCTION public.biz_demo_can(),public.biz_demo_build(),public.biz_demo_reset(boolean,boolean),public.biz_demo_read(),public.biz_demo_dashboard(jsonb),public.biz_demo_action(text,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.biz_demo_can(),public.biz_demo_reset(boolean,boolean),public.biz_demo_read(),public.biz_demo_dashboard(jsonb),public.biz_demo_action(text,text,jsonb) TO authenticated;
COMMENT ON TABLE public.biz_demo_sets IS 'Private per-admin simulation snapshots. No business foreign keys, operational writes, notification triggers, approval triggers or Sao triggers. Cleared only by owner-scoped demo RPC.';